changeSet.sql:
UPDATE eventconf_events
SET severity = (
xpath('//ns:severity/text()', xml_content::xml, ARRAY[
['ns', 'http://xmlns.opennms.org/xsd/eventconf']
])::text[]
)[1]
WHERE uei = 'uei.opennms.org/nodes/serviceMonitoringStopped';

UPDATE eventconf_events
SET severity = (
xpath('//ns:severity/text()', xml_content::xml, ARRAY[
['ns', 'http://xmlns.opennms.org/xsd/eventconf']
])::text[]
)[1]
WHERE uei = 'uei.opennms.org/nodes/nodeMonitoringStopped';

UPDATE eventconf_sources
SET event_count = (
    SELECT COUNT(*) FROM eventconf_events WHERE source_id = eventconf_sources.id
),
last_modified = CURRENT_TIMESTAMP
WHERE name = 'opennms.pollerd.events';
